    commentId: v.string(),
    folioId: v.string(),
    text: v.string(),
    author: v.string(),
    anchor: v.optional(v.string()),
    resolved: v.boolean(),
    createdAt: v.number(),
    updatedAt: v.number(),
  })
    .index("by_ownerId", ["ownerId"])
    .index("by_ownerId_commentId", ["ownerId", "commentId"]),

  userCommentReplies: defineTable({
    ownerId: v.string(),
    replyId: v.string(),
    commentId: v.string(),
    author: v.string(),
