  contextLedger: defineTable({
    userId: v.string(),
    entryId: v.string(),
    at: v.number(),
    layer: v.union(
      v.literal("house"),
      v.literal("collection"),
      v.literal("folio"),
      v.literal("amendment"),
      v.literal("charter"),
    ),
    ownerRef: v.string(),
    field: v.optional(v.string()),
    from: v.optional(v.string()),
    to: v.optional(v.string()),
    source: v.union(
      v.literal("interview"),
      v.literal("refine"),
      v.literal("amendment"),
      v.literal("house"),
      v.literal("collection"),
      v.literal("charter"),
      v.literal("manual"),
      v.literal("sync"),
    ),
    reason: v.optional(v.string()),
  })
    .index("by_userId_and_at", ["userId", "at"])
    .index("by_userId_and_entryId", ["userId", "entryId"]),
});

