import { setBackgroundRoomEnabled } from "./background-room";
import type { ConvexClient } from "convex/browser";
import { api } from "../../convex/_generated/api";
import {
  DEFAULT_AI_SETTINGS,
  type AiSettings,
  type AiProviderConfig,
  type WriterSettings,
  type ApparatusSettings,
  type RoomSettings,
} from "../types";
import {
  loadAiSettingsFromIdb,
  saveAiSettingsToIdb,
  loadWriterSettingsFromIdb,
  saveWriterSettingsToIdb,
  loadApparatusSettingsFromIdb,
  saveApparatusSettingsToIdb,
} from "./idb";
import {
  loadRoomSettingsLocally,
  saveRoomSettingsLocally,
} from "./convex-sync";
import {
  readThemePreference,
  writeThemePreference,
  applyTheme,
  normalizeThemePreference,
} from "./theme";
import {
  portablePreference,
  type PreferenceKind,
  type PreferenceValue,
} from "./account-preferences-contract";
import { createPreferenceSync } from "./preference-sync-engine";
import {
  readJournal,
  writeJournal,
  preferenceOwner,
  setPreferenceOwner,
  PREFERENCES_CHANGED,
  PREFERENCES_APPLIED,
  PREFERENCES_STORAGE_FAILED,
} from "./preference-outbox";
import { reportApplicationError } from "./application-diagnostics";

async function readLocal(kind: PreferenceKind): Promise<PreferenceValue> {
  const value =
    kind === "writer"
      ? await loadWriterSettingsFromIdb()
      : kind === "ai"
        ? ((await loadAiSettingsFromIdb()) ?? DEFAULT_AI_SETTINGS)
        : kind === "apparatus"
          ? await loadApparatusSettingsFromIdb()
          : kind === "room"
            ? await loadRoomSettingsLocally()
            : readThemePreference();
  return portablePreference(kind, value);
}
async function applyLocal(kind: PreferenceKind, value: PreferenceValue) {
  if (kind === "writer")
    await saveWriterSettingsToIdb(value as unknown as WriterSettings, false);
  if (kind === "apparatus") {
    const local = await loadApparatusSettingsFromIdb();
    await saveApparatusSettingsToIdb(
      { ...local, ...value } as ApparatusSettings,
      false,
    );
  }
  if (kind === "ai") {
    const local = (await loadAiSettingsFromIdb()) ?? DEFAULT_AI_SETTINGS;
    const remote = value as unknown as AiSettings;
    const providers = remote.providers.map((provider) => {
      const device = local.providers.find(
        (p) => p.id === provider.id && p.type === provider.type,
      );
      return {
        ...device,
        ...provider,
        apiKey: device?.apiKey ?? "",
        baseUrl: device?.baseUrl,
      } as AiProviderConfig;
    });
    await saveAiSettingsToIdb(
      {
        ...local,
        ...remote,
        providers,
        judgement: remote.judgement
          ? { ...local.judgement, ...remote.judgement }
          : undefined,
      },
      false,
    );
  }
  if (kind === "room") {
    await saveRoomSettingsLocally(value as unknown as RoomSettings, false);
    setBackgroundRoomEnabled(value.backgroundRoom !== false);
  }
  if (kind === "appearance") {
    const preference = normalizeThemePreference(value);
    writeThemePreference(preference, false);
    applyTheme(
      preference,
      document.documentElement,
      window.matchMedia("(prefers-color-scheme: dark)").matches,
    );
  }
  window.dispatchEvent(
    new CustomEvent(PREFERENCES_APPLIED, { detail: { kind } }),
  );
}

export function startAccountPreferences(client: ConvexClient, account: string) {
  const previousOwner = preferenceOwner();
  const seed = !previousOwner || previousOwner === account;
  setPreferenceOwner(account);
  // Anonymous changes seed an empty account, but never replace an existing
  // account's preferences simply because this is a new device.
  const engine = createPreferenceSync({
    seed,
    readLocal,
    applyLocal,
    readJournal: () => readJournal(account),
    writeJournal: (journal) => writeJournal(account, journal),
    pull: () => client.query(api.preferences.list, {}),
    put: (row) =>
      client.mutation(api.preferences.put, {
        kind: row.kind,
        json: row.json,
        expectedRevision: row.revision,
      }),
    onError: (error) =>
      reportApplicationError("twyne:preferences-sync", error, {
        source: "convex",
        title: "Settings sync is paused",
        dedupeKey: "preferences-sync",
      }),
  });
  const refresh = () => {
    void engine.refresh();
  };
  const stop = client.onUpdate(api.preferences.list, {}, refresh, (error) =>
    reportApplicationError("twyne:preferences-subscription", error, {
      source: "convex",
      title: "Settings sync is paused",
      dedupeKey: "preferences-sync",
    }),
  );
  const storageFailed = () => reportApplicationError("twyne:preferences-storage", new Error("Settings are saved locally, but the sync queue cannot be saved. Keep this tab open until settings sync completes."), { source: "convex", title: "Settings sync needs storage", dedupeKey: "preferences-storage" });
  window.addEventListener(PREFERENCES_STORAGE_FAILED, storageFailed);
  window.addEventListener(PREFERENCES_CHANGED, refresh);
  window.addEventListener("online", refresh);
  const onVisible = () => {
    if (document.visibilityState === "visible") refresh();
  };
  document.addEventListener("visibilitychange", onVisible);
  refresh();
  return () => {
    engine.dispose();
    stop();
    window.removeEventListener(PREFERENCES_CHANGED, refresh);
    window.removeEventListener(PREFERENCES_STORAGE_FAILED, storageFailed);
    window.removeEventListener("online", refresh);
    document.removeEventListener("visibilitychange", onVisible);
  };
}
import {
  PREFERENCE_KINDS,
  mergePreference,
  type PreferenceKind,
  type PreferenceValue,
} from "./account-preferences-contract";
import type { PreferenceJournal } from "./preference-outbox";
export interface PreferenceRow {
  kind: PreferenceKind;
  json: string;
  revision: number;
}
export interface PreferenceSyncDependencies {
  readJournal(): PreferenceJournal;
  writeJournal(journal: PreferenceJournal): void;
  readLocal(kind: PreferenceKind): Promise<PreferenceValue>;
  applyLocal(kind: PreferenceKind, value: PreferenceValue): Promise<void>;
  pull(): Promise<PreferenceRow[]>;
  put(row: PreferenceRow): Promise<{ accepted: boolean; revision: number }>;
  seed: boolean;
  onError(error: unknown): void;
}
export function createPreferenceSync(deps: PreferenceSyncDependencies) {
  let disposed = false;
  let running: Promise<void> | null = null;
  let again = false;
  async function run() {
    do {
      again = false;
      const remote = await deps.pull();
      if (disposed) return;
      for (const kind of PREFERENCE_KINDS) {
        if (disposed) return;
        const row = remote.find((row) => row.kind === kind);
        const journal = deps.readJournal();
        const base = journal.base[kind];
        const pending = journal.pending[kind];
        const server = row
          ? (JSON.parse(row.json) as PreferenceValue)
          : undefined;
        let next = server;
        if (pending)
          next =
            server && base
              ? (mergePreference(base, pending, server) as PreferenceValue)
              : pending;
        else if (!server && deps.seed) next = await deps.readLocal(kind);
        if (disposed || !next) continue;
        if (JSON.stringify(next) !== JSON.stringify(server)) {
          const result = await deps.put({
            kind,
            json: JSON.stringify(next),
            revision: row?.revision ?? 0,
          });
          if (disposed) return;
          if (!result.accepted) {
            again = true;
            continue;
          }
        }
        const latest = deps.readJournal();
        // A new edit during the network request must survive its acknowledgement.
        if (JSON.stringify(latest.pending[kind]) !== JSON.stringify(pending)) {
          again = true;
          continue;
        }
        latest.base[kind] = next;
        delete latest.pending[kind];
        deps.writeJournal(latest);
        if (
          JSON.stringify(await deps.readLocal(kind)) !== JSON.stringify(next)
        ) {
          if (disposed || deps.readJournal().pending[kind]) {
            again = true;
            continue;
          }
          await deps.applyLocal(kind, next);
        }
      }
    } while (again && !disposed);
  }
  return {
    refresh(): Promise<void> {
      if (disposed) return Promise.resolve();
      if (running) {
        again = true;
        return running;
      }
      running = run()
        .catch(deps.onError)
        .finally(() => {
          running = null;
        });
      return running;
    },
    dispose() {
      disposed = true;
    },
  };
}

