 * itself. Guests still get a (never forced) sign-up offer once the brief lands.
 */
export default component$(() => {
  const nav = useNavigate();
  const auth = useAuth();
  // Once the brief is saved we offer (but never force) sign-up.
  const briefDone = useSignal(false);
  const filingState = useSignal<DossierFilingState>("idle");
  const store = useStore<OnboardingStore>({
    hydrated: false,
    style: "form",
    formAnswers: null,
    formAttachments: [],
    formProbes: [],
    draftScope: "create:new",
    draftBase: "0",
    folioId: null,
    folioName: "",
    initialMaterial: "",
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async () => {
    const [writer, folios, activeFolioId] = await Promise.all([
      loadWriterSettingsFromIdb(),
      loadFoliosFromIdb(),
      loadActiveFolioIdFromIdb(),
    ]);
    store.style = writer.interviewStyle;
    const requestedFolioId = new URLSearchParams(window.location.search).get(
      "folio",
    );
    const folio =
      folios.find((candidate) => candidate.id === requestedFolioId) ??
      folios.find((candidate) => candidate.id === activeFolioId) ??
      null;
    store.folioId = folio?.id ?? null;
    store.draftScope = `create:${store.folioId ?? "new"}`;
    store.folioName = folio?.name ?? "";
    // A folio named in the editor already has a title; start the brief there.
    const folioTitle = briefTitleFromFolioName(store.folioName);
    if (folioTitle) store.formAnswers = { workingTitle: folioTitle };
    const savedBrief = await loadProjectBriefForFolio(store.folioId);
    store.draftBase = String(savedBrief?.updatedAt ?? 0);
    if (savedBrief) {
      store.formAnswers = savedBrief.answers;
      store.formAttachments = savedBrief.attachments;
      store.formProbes = savedBrief.probes ?? [];
      // A cleared brief from Start over intentionally stays in the interview.
      briefDone.value =
        Object.values(savedBrief.answers).some((value) => value.trim()) ||
        savedBrief.attachments.length > 0 ||
        (savedBrief.probes?.length ?? 0) > 0;
    }
    // Pull the manuscript text the refine page stashed when the writer hit
    // "Start over", then clear it so a subsequent ordinary /dossier/create
    // visit doesn't see a stale carry-over.
    store.initialMaterial = loadStartingMaterial();
    clearStartingMaterial();
    store.hydrated = true;
  });

  const completeOnboarding$ = $(
    async (
      answers: ProjectInterviewAnswers,
      existingMaterial?: string,
      filename?: string,
      attachments?: DossierAttachment[],
      probes?: DossierProbe[],
    ) => {
      filingState.value = "filing";

          onSwitchSurface$={$(() => {
            store.style = "form";
          })}
          initialMaterial={store.initialMaterial}
          onComplete$={({ answers, attachments, probes }) =>
            completeOnboarding$(
              answers,
              undefined,
              undefined,
              attachments,
              probes,
            )
          }
          onUseForm$={({ answers, attachments }) => {
            store.formAnswers = answers;
            store.formAttachments = attachments;
            store.style = "form";
          }}
        />
      </div>
    );
  }

  // The form surface owns the viewport, and files its own chrome into the
  // folio's top edge rather than stacking a page-wide bar above it.
  return (
    <div class={DOSSIER_ROUTE_CLASS}>
      <AntiTabulaRasa
        mode="first-run"
        draftScope={store.draftScope}
        draftBase={store.draftBase}
        filingState={filingState.value}
        chromeBackHref={store.folioId ? "/editor/" : "/"}
        chromeBackLabel={store.folioId ? "Back to desk" : "Back home"}
        onSwitchSurface$={$(() => {
          store.style = "conversational";
        })}
        initialAnswers={
          store.formAnswers as ProjectInterviewAnswers | null | undefined
        }
        initialAttachments={store.formAttachments}
        initialProbes={store.formProbes}
        initialMaterial={store.initialMaterial}
        onSubmit$={completeOnboarding$}
      />
    </div>
  );
});

